CREATE DATABASE IF NOT EXISTS autocare_core_db;
USE autocare_core_db;
CREATE TABLE users (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, phone VARCHAR(10) NOT NULL, password VARCHAR(255) NOT NULL, role ENUM('admin','customer') NOT NULL DEFAULT 'customer', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE services (id INT AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, price DECIMAL(10,2) NOT NULL, duration INT NOT NULL, status ENUM('Active','Inactive') DEFAULT 'Active');
CREATE TABLE vehicles (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, vehicle_type VARCHAR(30) NOT NULL, brand VARCHAR(80) NOT NULL, model VARCHAR(80) NOT NULL, registration_number VARCHAR(30) NOT NULL UNIQUE, manufacturing_year INT NOT NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE bookings (id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, vehicle_id INT NOT NULL, service_id INT NOT NULL, booking_date DATE NOT NULL, notes TEXT, status ENUM('Pending','Confirmed','In Progress','Completed','Cancelled') DEFAULT 'Pending', FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(vehicle_id) REFERENCES vehicles(id) ON DELETE CASCADE, FOREIGN KEY(service_id) REFERENCES services(id));
